import{_ as e,o as i,c as o,ag as t}from"./chunks/framework.DXGyWiRo.js";const c=JSON.parse('{"title":"Akebi 报错与错误提示","description":"","frontmatter":{},"headers":[],"relativePath":"genshin/akebi_errors.md","filePath":"genshin/akebi_errors.md"}'),l={name:"genshin/akebi_errors.md"};function r(n,a,d,u,s,h){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="akebi-报错与错误提示" tabindex="-1">Akebi 报错与错误提示 <a class="header-anchor" href="#akebi-报错与错误提示" aria-label="Permalink to &quot;Akebi 报错与错误提示&quot;">​</a></h1><p><strong>主要处理 Akebi 启动时遇到的问题，若 Akebi 成功载入并打开 GUI 后遇到一些问题</strong></p><p>在解决问题之前，请先保证自己已经做了以下准备：</p><blockquote><p>杀毒已经完全关闭 以管理员身份运行 游戏已更新到最新版本</p></blockquote><h2 id="常见报错及解决方法" tabindex="-1">常见报错及解决方法 <a class="header-anchor" href="#常见报错及解决方法" aria-label="Permalink to &quot;常见报错及解决方法&quot;">​</a></h2><h3 id="_1-failed-to-initialize" tabindex="-1">1. &quot;Failed to initialize&quot; <a class="header-anchor" href="#_1-failed-to-initialize" aria-label="Permalink to &quot;1. &quot;Failed to initialize&quot;&quot;">​</a></h3><ul><li>尝试重新下载并解压注入器</li><li>确保路径没有中文</li><li>关闭所有杀毒软件</li></ul><h3 id="_2-driver-not-loaded" tabindex="-1">2. &quot;Driver not loaded&quot; <a class="header-anchor" href="#_2-driver-not-loaded" aria-label="Permalink to &quot;2. &quot;Driver not loaded&quot;&quot;">​</a></h3><ul><li>以管理员身份重新运行</li><li>重启电脑后再次尝试</li><li>检查系统是否为 Windows 10 或 Windows 11</li></ul><h3 id="_3-game-not-found" tabindex="-1">3. &quot;Game not found&quot; <a class="header-anchor" href="#_3-game-not-found" aria-label="Permalink to &quot;3. &quot;Game not found&quot;&quot;">​</a></h3><ul><li>确保原神游戏已经启动</li><li>检查游戏窗口模式是否为无边框窗口</li><li>尝试使用官方启动器修复游戏文件</li></ul><h3 id="_4-注入器闪退" tabindex="-1">4. 注入器闪退 <a class="header-anchor" href="#_4-注入器闪退" aria-label="Permalink to &quot;4. 注入器闪退&quot;">​</a></h3><ul><li>关闭所有杀毒和防护软件</li><li>检查 .NET 运行库是否安装完整</li><li>尝试兼容模式运行（Windows 8）</li></ul>',13)])])}const q=e(l,[["render",r]]);export{c as __pageData,q as default};
